const vec3 col1 = vec3(15./255., 25./255., 128./255.);//15, 25, 128
const vec3 col2 = vec3(93./255., 146./255., 245./255.);//93, 146, 245

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //split the screen up into squares
    float squaresize = 20.0;
    vec2 newfragCoord = floor(fragCoord / squaresize) * squaresize;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = newfragCoord/iResolution.xy;

    //get brightness from texture
    vec3 col = texture(iChannel0, uv).rgb;
    if(length(col - vec3(0.05, 0.64, 0.15)) < 0.25){col = vec3(0.0,0.0,0.0);};//bad greenscreen removal
    float bright = (col.r + col.g + col.b) / 3.0;

    float brightlength = ((1.0 - bright) * squaresize)/2.0;

    col = col1;
    //look for sub-square, size dependant on brightness
    if( fragCoord.x > newfragCoord.x + brightlength &&
        fragCoord.x < newfragCoord.x + squaresize - brightlength &&
        fragCoord.y > newfragCoord.y + brightlength &&
        fragCoord.y < newfragCoord.y + squaresize - brightlength
        ){
        col = col2;
    };

    // Output to screen
    fragColor = vec4(col,1.0);
}
